INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Leasing immer teurer als Kauf ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann kosteneffizienter sein"}, {"text": "Ja", "correct": false, "because": "Abhängig von Bedingungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Leasing für IT-Hardware plane?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Ermöglicht Anpassung"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Leasing für IT-Ausstattung?', 5, '[{"text": "Liquiditätsschonung", "correct": true, "because": "Keine hohen Anfangskosten"}, {"text": "Aktuelle Technik", "correct": true, "because": "Ermöglicht regelmäßige Updates"}, {"text": "Hohe Anschaffungskosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Langfristige Bindung", "correct": false, "because": "Eher Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leasing schont das Budget. b) Es bedeutet immer Eigentum.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum bleibt beim Leasinggeber"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Leasing für IT-Geräte nutze?', 4, '[{"text": "Vertragslaufzeit", "correct": false, "because": "Bestimmt Bindung"}, {"text": "Leasingraten", "correct": false, "because": "Beeinflusst Kosten"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Leasingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Leasing immer für Hardware geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig für Hardware genutzt"}, {"text": "Nein", "correct": false, "because": "Auch für Software möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Leasing für IT-Ausstattung?', 3, '[{"text": "Kostenkontrolle", "correct": true, "because": "Fixe Raten planbar"}, {"text": "Sofortiges Eigentum", "correct": false, "because": "Kein Eigentum"}, {"text": "Weniger Flexibilität", "correct": false, "because": "Fördert Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Leasing in der IT attraktiv?', 5, '[{"text": "Steuerliche Vorteile", "correct": true, "because": "Raten absetzbar"}, {"text": "Technologieaktualität", "correct": true, "because": "Regelmäßige Erneuerung"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Eigentumsverlust", "correct": false, "because": "Eher Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Leasing ist flexibel. b) Es ist immer günstiger als Kauf. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Leasingvertrag in der IT?', 4, '[{"text": "Vertragsdauer", "correct": false, "because": "Bestimmt Laufzeit"}, {"text": "Kostenübersicht", "correct": false, "because": "Wichtig für Planung"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Vertragsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Leasing in der IT immer langfristig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kurzfristig möglich"}, {"text": "Ja", "correct": false, "because": "Laufzeit variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Leasing für IT-Hardware?', 4, '[{"text": "Kein Eigentum", "correct": true, "because": "Bleibt beim Leasinggeber"}, {"text": "Laufzeitbindung", "correct": true, "because": "Einschränkt Flexibilität"}, {"text": "Geringere Kosten", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Leasing nur für große Firmen sinnvoll ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Leasing für IT-Geräte zu optimieren?', 3, '[{"text": "Vertragsverhandlung", "correct": true, "because": "Passt Konditionen an"}, {"text": "Teure Hardware", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Verträge", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leasing ermöglicht Technik-Updates. b) Es ist immer kurzfristig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Laufzeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich beim Leasing von IT-Ausstattung?', 5, '[{"text": "Leasingraten", "correct": true, "because": "Beeinflusst Budget"}, {"text": "Vertragsflexibilität", "correct": true, "because": "Ermöglicht Anpassung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Marketingziele", "correct": false, "because": "Kein Leasingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Leasing für IT-Hardware plane?', 3, '[{"text": "Restwert", "correct": false, "because": "Beeinflusst Kosten"}, {"text": "Laufzeit", "correct": false, "because": "Definiert Bindung"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Leasingfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Spart Leasing in der IT immer Kosten?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Bedingungen"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Leasing für Software üblich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig bei Lizenzen"}, {"text": "Nein", "correct": false, "because": "Auch Software leasebar"}]'),
